function makeStub(bin, name, body) {
  const path = join(bin, name);
  writeFileSync(
    path,
    `#!/usr/bin/env bash\nset -euo pipefail\nprintf '${name} %s\\n' "$*" >> "$DETRAN_TEST_STUB_CALLS"\n${body}\n`,
    { mode: 0o755 },
  );
}

