    return { ...result, calls: readFileSync(callsPath, 'utf8') };
  } finally {
    rmSync(stateDir, { recursive: true, force: true });
    rmSync(bin, { recursive: true, force: true });
  }
}

function runStack(args, env, stubs) {
  return run('bash', [stackScript, ...args], env, stubs);
}

